1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1.0">
6	<title>Architecture Diagram — Reference Template</title>
7	<!--
8	  Reference template for the visual-explainer skill: CSS Grid architecture layout.
9	  Warm terracotta/sage palette — distinctly different from the teal (mermaid)
10	  and rose (data-table) templates so agents absorb variety, not a single palette.
11	  Key patterns demonstrated:
12	  - Warm non-default palette (terracotta + sage, NOT indigo/violet)
13	  - Depth tiers: hero (input sources), default (mid sections), recessed (callout)
14	  - Asymmetric background atmosphere (off-center gradient mesh)
15	  - Large heading (38px) for typographic contrast
16	  - Section cards with colored accent borders and dot labels
17	  - Vertical flow arrows between sections (inline SVG)
18	  - Horizontal pipeline with step boxes and arrow separators
19	  - Parallel branch within a pipeline
20	  - Color-coded legend, three-column output row
21	  - Staggered fade-in via --i CSS variable (works with interleaved elements)
22	  - Reduced motion respect, responsive single-column fallback
23	-->
24	<link rel="preconnect" href="https://fonts.googleapis.com">
25	<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
26	<link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500;600&family=IBM+Plex+Sans:wght@400;500;600;700&display=swap" rel="stylesheet">
27	<style>
28	  /* ============ THEME ============ */
29	  :root {
30	    --font-body: 'IBM Plex Sans', system-ui, sans-serif;
31	    --font-mono: 'IBM Plex Mono', 'SF Mono', Consolas, monospace;
32	
33	    /* Light theme — warm terracotta + sage palette */
34	    --bg: #faf7f5;
35	    --surface: #ffffff;
36	    --surface2: #f5f0ec;
37	    --surface-elevated: #fff9f5;
38	    --border: rgba(0, 0, 0, 0.07);
39	    --border-bright: rgba(0, 0, 0, 0.14);
40	    --text: #292017;
41	    --text-dim: #8a7e72;
42	    --accent: #c2410c;
43	    --accent-dim: rgba(194, 65, 12, 0.07);
44	    --green: #4d7c0f;
45	    --green-dim: rgba(77, 124, 15, 0.07);
46	    --orange: #b45309;
47	    --orange-dim: rgba(180, 83, 9, 0.07);
48	    --sage: #65a30d;
49	    --sage-dim: rgba(101, 163, 13, 0.07);
50	    --teal: #0f766e;
51	    --teal-dim: rgba(15, 118, 110, 0.07);
52	    --plum: #9f1239;
53	    --plum-dim: rgba(159, 18, 57, 0.07);
54	  }
55	
56	  @media (prefers-color-scheme: dark) {
57	    :root {
58	      --bg: #1a1412;
59	      --surface: #231d1a;
60	      --surface2: #2e2622;
61	      --surface-elevated: #352d28;
62	      --border: rgba(255, 255, 255, 0.06);
63	      --border-bright: rgba(255, 255, 255, 0.12);
64	      --text: #ede5dd;
65	      --text-dim: #a69889;
66	      --accent: #fb923c;
67	      --accent-dim: rgba(251, 146, 60, 0.12);
68	      --green: #a3e635;
69	      --green-dim: rgba(163, 230, 53, 0.1);
70	      --orange: #fbbf24;
71	      --orange-dim: rgba(251, 191, 36, 0.1);
72	      --sage: #bef264;
73	      --sage-dim: rgba(190, 242, 100, 0.1);
74	      --teal: #5eead4;
75	      --teal-dim: rgba(94, 234, 212, 0.1);
76	      --plum: #fda4af;
77	      --plum-dim: rgba(253, 164, 175, 0.1);
78	    }
79	  }
80	
81	  /* ============ RESET + BASE ============ */
82	  * { margin: 0; padding: 0; box-sizing: border-box; }
83	
84	  body {
85	    background: var(--bg);
86	    background-image:
87	      radial-gradient(ellipse at 20% 0%, var(--accent-dim) 0%, transparent 50%),
88	      radial-gradient(ellipse at 80% 100%, var(--sage-dim) 0%, transparent 40%);
89	    color: var(--text);
90	    font-family: var(--font-body);
91	    padding: 40px;
92	    min-height: 100vh;
93	  }
94	
95	  /* ============ ANIMATION ============ */
96	  @keyframes fadeUp {
97	    from { opacity: 0; transform: translateY(12px); }
98	    to { opacity: 1; transform: translateY(0); }
99	  }
100	
101	  .section, .flow-arrow {
102	    animation: fadeUp 0.4s ease-out both;
103	    animation-delay: calc(var(--i, 0) * 0.06s);
104	  }
105	
106	  @media (prefers-reduced-motion: reduce) {
107	    *, *::before, *::after {
108	      animation-duration: 0.01ms !important;
109	      animation-delay: 0ms !important;
110	      transition-duration: 0.01ms !important;
111	    }
112	  }
113	
114	  /* ============ TYPOGRAPHY ============ */
115	  h1 {
116	    font-size: 38px;
117	    font-weight: 700;
118	    letter-spacing: -1px;
119	    margin-bottom: 6px;
120	    text-wrap: balance;
121	  }
122	
123	  .subtitle {
124	    color: var(--text-dim);
125	    font-size: 14px;
126	    margin-bottom: 40px;
127	    font-family: var(--font-mono);
128	  }
129	
130	  /* ============ LAYOUT ============ */
131	  .diagram {
132	    display: grid;
133	    grid-template-columns: 1fr;
134	    gap: 24px;
135	    max-width: 1100px;
136	    margin: 0 auto;
137	  }
138	
139	  /* ============ SECTION CARD ============ */
140	  .section {
141	    background: var(--surface);
142	    border: 1px solid var(--border);
143	    border-radius: 12px;
144	    padding: 20px 24px;
145	  }
146	
147	  .section--hero {
148	    background: var(--surface-elevated);
149	    border-color: color-mix(in srgb, var(--border) 50%, var(--accent) 50%);
150	    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.06);
151	    padding: 28px 32px;
152	  }
153	
154	  .section--recessed {
155	    background: var(--surface2);
156	    box-shadow: inset 0 1px 3px rgba(0, 0, 0, 0.04);
157	  }
158	
159	  .section-label {
160	    font-family: var(--font-mono);
161	    font-size: 11px;
162	    font-weight: 600;
163	    text-transform: uppercase;
164	    letter-spacing: 1.5px;
165	    margin-bottom: 16px;
166	    display: flex;
167	    align-items: center;
168	    gap: 8px;
169	  }
170	
171	  .section-label .dot {
172	    width: 8px;
173	    height: 8px;
174	    border-radius: 50%;
175	    display: inline-block;
176	  }
177	
178	  /* Color variants */
179	  .section--accent { border-color: var(--accent-dim); }
180	  .section--accent .section-label { color: var(--accent); }
181	  .section--accent .section-label .dot { background: var(--accent); }
182	
183	  .section--green { border-color: var(--green-dim); }
184	  .section--green .section-label { color: var(--green); }
185	  .section--green .section-label .dot { background: var(--green); }
186	
187	  .section--orange { border-color: var(--orange-dim); }
188	  .section--orange .section-label { color: var(--orange); }
189	  .section--orange .section-label .dot { background: var(--orange); }
190	
191	  .section--sage { border-color: var(--sage-dim); }
192	  .section--sage .section-label { color: var(--sage); }
193	  .section--sage .section-label .dot { background: var(--sage); }
194	
195	  .section--teal { border-color: var(--teal-dim); }
196	  .section--teal .section-label { color: var(--teal); }
197	  .section--teal .section-label .dot { background: var(--teal); }
198	
199	  .section--plum { border-color: var(--plum-dim); }
200	  .section--plum .section-label { color: var(--plum); }
201	  .section--plum .section-label .dot { background: var(--plum); }
202	
203	  /* ============ INNER GRID ============ */
204	  .inner-grid {
205	    display: grid;
206	    grid-template-columns: 1fr 1fr;
207	    gap: 12px;
208	  }
209	
210	  .inner-card {
211	    background: var(--surface2);
212	    border: 1px solid var(--border);
213	    border-radius: 8px;
214	    padding: 12px 16px;
215	  }
216	
217	  .inner-card .title {
218	    font-weight: 600;
219	    font-size: 13px;
220	    margin-bottom: 4px;
221	  }
222	
223	  .inner-card .desc {
224	    color: var(--text-dim);
225	    font-size: 12px;
226	    line-height: 1.5;
227	  }
228	
229	  .inner-card code {
230	    font-family: var(--font-mono);
231	    font-size: 11px;
232	    background: var(--accent-dim);
233	    color: var(--accent);
234	    padding: 1px 5px;
235	    border-radius: 3px;
236	  }
237	
238	  /* ============ FLOW ARROW ============ */
239	  .flow-arrow {
240	    display: flex;
241	    justify-content: center;
242	    align-items: center;
243	    gap: 8px;
244	    color: var(--text-dim);
245	    font-family: var(--font-mono);
246	    font-size: 12px;
247	    padding: 4px 0;
248	  }
249	
250	  .flow-arrow svg {
251	    width: 20px;
252	    height: 20px;
253	    fill: none;
254	    stroke: var(--border-bright);
255	    stroke-width: 2;
256	    stroke-linecap: round;
257	    stroke-linejoin: round;
258	  }
259	
260	  /* ============ PIPELINE ============ */
261	  .pipeline {
262	    display: flex;
263	    gap: 0;
264	    align-items: stretch;
265	    overflow-x: auto;
266	    padding-bottom: 4px;
267	  }
268	
269	  .pipeline-step {
270	    background: var(--surface);
271	    border: 1px solid var(--border);
272	    border-radius: 8px;
273	    padding: 10px 12px;
274	    min-width: 120px;
275	    flex-shrink: 0;
276	    text-align: center;
277	  }
278	
279	  .pipeline-step .step-num {
280	    font-family: var(--font-mono);
281	    font-size: 10px;
282	    font-weight: 600;
283	    margin-bottom: 4px;
284	  }
285	
286	  .pipeline-step .step-name {
287	    font-size: 12px;
288	    font-weight: 600;
289	    margin-bottom: 3px;
290	  }
291	
292	  .pipeline-step .step-detail {
293	    font-size: 10px;
294	    color: var(--text-dim);
295	    line-height: 1.4;
296	  }
297	
298	  /* Step color variants */
299	  .pipeline-step--teal { border-color: var(--teal-dim); }
300	  .pipeline-step--teal .step-num { color: var(--teal); }
301	
302	  .pipeline-step--sage { border-color: var(--sage-dim); }
303	  .pipeline-step--sage .step-num { color: var(--sage); }
304	
305	  .pipeline-step--orange { border-color: var(--orange-dim); }
306	  .pipeline-step--orange .step-num { color: var(--orange); }
307	
308	  .pipeline-step--green { border-color: var(--green-dim); }
309	  .pipeline-step--green .step-num { color: var(--green); }
310	
311	  .pipeline-arrow {
312	    display: flex;
313	    align-items: center;
314	    padding: 0 2px;
315	    color: var(--border-bright);
316	    font-size: 16px;
317	    flex-shrink: 0;
318	  }
319	
320	  .pipeline-parallel {
321	    display: flex;
322	    flex-direction: column;
323	    gap: 4px;
324	  }
325	
326	  /* ============ THREE COLUMN ROW ============ */
327	  .three-col {
328	    display: grid;
329	    grid-template-columns: 1fr 1fr 1fr;
330	    gap: 16px;
331	  }
332	
333	  /* ============ LIST ============ */
334	  .node-list {
335	    list-style: none;
336	    font-size: 12px;
337	    line-height: 1.8;
338	  }
339	
340	  .node-list li {
341	    padding-left: 14px;
342	    position: relative;
343	  }
344	
345	  .node-list li::before {
346	    content: '›';
347	    color: var(--text-dim);
348	    font-weight: 600;
349	    position: absolute;
350	    left: 0;
351	  }
352	
353	  .node-list code {
354	    font-family: var(--font-mono);
355	    font-size: 11px;
356	    background: var(--accent-dim);
357	    color: var(--accent);
358	    padding: 1px 5px;
359	    border-radius: 3px;
360	  }
361	
362	  /* ============ CALLOUT ============ */
363	  .callout {
364	    background: var(--surface2);
365	    border: 1px solid var(--border);
366	    border-left: 3px solid var(--accent);
367	    border-radius: 0 8px 8px 0;
368	    padding: 14px 18px;
369	    font-size: 13px;
370	    line-height: 1.6;
371	    color: var(--text-dim);
372	  }
373	
374	  .callout strong { color: var(--text); font-weight: 600; }
375	
376	  .callout code {
377	    font-family: var(--font-mono);
378	    font-size: 11px;
379	    background: var(--accent-dim);
380	    color: var(--accent);
381	    padding: 1px 5px;
382	    border-radius: 3px;
383	  }
384	
385	  /* ============ LEGEND ============ */
386	  .legend {
387	    display: flex;
388	    gap: 20px;
389	    flex-wrap: wrap;
390	  }
391	
392	  .legend-item {
393	    display: flex;
394	    align-items: center;
395	    gap: 6px;
396	    font-size: 11px;
397	    color: var(--text-dim);
398	    font-family: var(--font-mono);
399	  }
400	
401	  .legend-swatch {
402	    width: 12px;
403	    height: 12px;
404	    border-radius: 3px;
405	  }
406	
407	  /* ============ SOURCE PILLS ============ */
408	  .sources {
409	    display: flex;
410	    gap: 12px;
411	    flex-wrap: wrap;
412	    justify-content: center;
413	  }
414	
415	  .source {
416	    background: var(--surface2);
417	    border: 1px solid var(--border);
418	    border-radius: 8px;
419	    padding: 10px 18px;
420	    font-family: var(--font-mono);
421	    font-size: 13px;
422	    font-weight: 500;
423	    display: flex;
424	    align-items: center;
425	    gap: 8px;
426	    transition: border-color 0.2s;
427	  }
428	
429	  .source:hover { border-color: var(--border-bright); }
430	
431	  /* ============ RESPONSIVE ============ */
432	  @media (max-width: 768px) {
433	    body { padding: 20px; }
434	    .inner-grid { grid-template-columns: 1fr; }
435	    .three-col { grid-template-columns: 1fr; }
436	    .pipeline { flex-wrap: wrap; gap: 6px; }
437	    .pipeline-arrow { display: none; }
438	  }
439	</style>
440	</head>
441	<body>
442	
443	<h1>System Architecture</h1>
444	<p class="subtitle">reference template &mdash; architecture diagram pattern</p>
445	
446	<div class="diagram">
447	
448	  <!-- Source pills row — hero depth for the entry point -->
449	  <div class="section section--hero" style="--i:0">
450	    <div class="section-label"><span class="dot" style="background:var(--text-dim)"></span> Input Sources</div>
451	    <div class="sources">
452	      <div class="source"><span>💬</span> Slack</div>
453	      <div class="source"><span>🐙</span> GitHub</div>
454	      <div class="source"><span>📧</span> Email</div>
455	    </div>
456	  </div>
457	
458	  <!-- Flow arrow -->
459	  <div class="flow-arrow" style="--i:1">
460	    <svg viewBox="0 0 20 20"><path d="M10 4 L10 16 M6 12 L10 16 L14 12"/></svg>
461	    incoming events
462	  </div>
463	
464	  <!-- Gateway section with inner grid -->
465	  <div class="section section--accent" style="--i:2">
466	    <div class="section-label"><span class="dot"></span> Gateway Layer</div>
467	    <div class="inner-grid">
468	      <div class="inner-card">
469	        <div class="title">Router</div>
470	        <div class="desc">Routes messages to agents via <code>resolveRoute()</code></div>
471	      </div>
472	      <div class="inner-card">
473	        <div class="title">HTTP Server</div>
474	        <div class="desc">Plugin routes + handlers for webhooks and API</div>
475	      </div>
476	    </div>
477	  </div>
478	
479	  <div class="flow-arrow" style="--i:3">
480	    <svg viewBox="0 0 20 20"><path d="M10 4 L10 16 M6 12 L10 16 L14 12"/></svg>
481	    pipeline entry
482	  </div>
483	
484	  <!-- Pipeline section -->
485	  <div class="section section--green" style="--i:4">
486	    <div class="section-label"><span class="dot"></span> Processing Pipeline</div>
487	    <div class="legend" style="margin-bottom:14px">
488	      <div class="legend-item"><div class="legend-swatch" style="background:var(--teal-dim);border:1px solid var(--teal)"></div>no LLM</div>
489	      <div class="legend-item"><div class="legend-swatch" style="background:var(--sage-dim);border:1px solid var(--sage)"></div>LLM call</div>
490	      <div class="legend-item"><div class="legend-swatch" style="background:var(--orange-dim);border:1px solid var(--orange)"></div>embedding</div>
491	      <div class="legend-item"><div class="legend-swatch" style="background:var(--green-dim);border:1px solid var(--green)"></div>DB write</div>
492	    </div>
493	    <div class="pipeline">
494	      <div class="pipeline-step pipeline-step--teal">
495	        <div class="step-num">STEP 0</div>
