order-bright: rgba(0, 0, 0, 0.14);\n    --text: #292017;\n    --text-dim: #8a7e72;\n    --accent: #c2410c;\n    --accent-dim: rgba(194, 65, 12, 0.07);\n    --green: #4d7c0f;\n    --green-dim: rgba(77, 124, 15, 0.07);\n    --orange: #b45309;\n    --orange-dim: rgba(180, 83, 9, 0.07);\n    --sage: #65a30d;\n    --sage-dim: rgba(101, 163, 13, 0.07);\n    --teal: #0f766e;\n    --teal-dim: rgba(15, 118, 110, 0.07);\n    --plum: #9f1239;\n    --plum-dim: rgba(159, 18, 57, 0.07);\n  }\n\n  @media (prefers-color-scheme: dark) {\n    :root {\n      --bg: #1a1412;\n      --surface: #231d1a;\n      --surface2: #2e2622;\n      --surface-elevated: #352d28;\n      --border: rgba(255, 255, 255, 0.06);\n      --border-bright: rgba(255, 255, 255, 0.12);\n      --text: #ede5dd;\n      --text-dim: #a69889;\n      --accent: #fb923c;\n      --accent-dim: rgba(251, 146, 60, 0.12);\n      --green: #a3e635;\n      --green-dim: rgba(163, 230, 53, 0.1);\n      --orange: #fbbf24;\n      --orange-dim: rgba(251, 191, 36, 0.1);\n      --sage: #bef264;\n      --sage-dim: rgba(190, 242, 100, 0.1);\n      --teal: #5eead4;\n      --teal-dim: rgba(94, 234, 212, 0.1);\n      --plum: #fda4af;\n      --plum-dim: rgba(253, 164, 175, 0.1);\n    }\n  }\n\n  /* ============ RESET + BASE ============ */\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n\n  body {\n    background: var(--bg);\n    background-image:\n      radial-gradient(ellipse at 20% 0%, var(--accent-dim) 0%, transparent 50%),\n      radial-gradient(ellipse at 80% 100%, var(--sage-dim) 0%, transparent 40%);\n    color: var(--text);\n    font-family: var(--font-body);\n    padding: 40px;\n    min-height: 100vh;\n  }\n\n  /* ============ ANIMATION ============ */\n  @keyframes fadeUp {\n    from { opacity: 0; transform: translateY(12px); }\n    to { opacity: 1; transform: translateY(0); }\n  }\n\n  .section, .flow-arrow {\n    animation: fadeUp 0.4s ease-out both;\n    animation-delay: calc(var(--i, 0) * 0.06s);\n  }\n\n  @media (prefers-reduced-motion: reduce) {\n    *, *::before, *::after {\n      animation-duration: 0.01ms !important;\n      animation-delay: 0ms !important;\n      transition-duration: 0.01ms !important;\n    }\n  }\n\n  /* ============ TYPOGRAPHY ============ */\n  h1 {\n    font-size: 38px;\n    font-weight: 700;\n    letter-spacing: -1px;\n    margin-bottom: 6px;\n    text-wrap: balance;\n  }\n\n  .subtitle {\n    color: var(--text-dim);\n    font-size: 14px;\n    margin-bottom: 40px;\n    font-family: var(--font-mono);\n  }\n\n  /* ============ LAYOUT ============ */\n  .diagram {\n    display: grid;\n    grid-template-columns: 1fr;\n    gap: 24px;\n    max-width: 1100px;\n    margin: 0 auto;\n  }\n\n  /* ============ SECTION CARD ============ */\n  .section {\n    background: var(--surface);\n    border: 1px solid var(--border);\n    border-radius: 12px;\n    padding: 20px 24px;\n  }\n\n  .section--hero {\n    background: var(--surface-elevated);\n    border-color: color-mix(in srgb, var(--border) 50%, var(--accent) 50%);\n    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.06);\n    padding: 28px 32px;\n  }\n\n  .section--recessed {\n    background: var(--surface2);\n    box-shadow: inset 0 1px 3px rgba(0, 0, 0, 0.04);\n  }\n\n  .section-label {\n    font-family: var(--font-mono);\n    font-size: 11px;\n    font-weight: 600;\n    text-transform: uppercase;\n    letter-spacing: 1.5px;\n    margin-bottom: 16px;\n    display: flex;\n    align-items: center;\n    gap: 8px;\n  }\n\n  .section-label .dot {\n    width: 8px;\n    height: 8px;\n    border-radius: 50%;\n    display: inline-block;\n  }\n\n  /* Color variants */\n  .section--accent { border-color: var(--accent-dim); }\n  .section--accent .section-label { color: var(--accent); }\n  .section--accent .section-label .dot { background: var(--accent); }\n\n  .section--green { border-color: var(--green-dim); }\n  .section--green .section-label { color: var(--green); }\n  .section--green .section-label .dot { background: var(--green); }\n\n  .section--orange { border-color: var(--orange-dim); }\n  .section--orange .section-label { color: var(--orange); }\n  .section--orange .section-label .dot { background: var(--orange); }\n\n  .section--sage { border-color: var(--sage-dim); }\n  .section--sage .section-label { color: var(--sage); }\n  .section--sage .section-label .dot { background: var(--sage); }\n\n  .section--teal { border-color: var(--teal-dim); }\n  .section--teal .section-label { color: var(--teal); }\n  .section--teal .section-label .dot { background: var(--teal); }\n\n  .section--plum { border-color: var(--plum-dim); }\n  .section--plum .section-label { color: var(--plum); }\n  .section--plum .section-label .dot { background: var(--plum); }\n\n  /* ============ INNER GRID ============ */\n  .inner-grid {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 12px;\n  }\n\n  .inner-card {\n    background: var(--surface2);\n    border: 1px solid var(--border);\n    border-radius: 8px;\n    padding: 12px 16px;\n  }\n\n  .inner-card .title {\n    font-weight: 600;\n    font-size: 13px;\n    margin-bottom: 4px;\n  }\n\n  .inner-card .desc {\n    color: var(--text-dim);\n    font-size: 12px;\n    line-height: 1.5;\n  }\n\n  .inner-card code {\n    font-family: var(--font-mono);\n    font-size: 11px;\n    background: var(--accent-dim);\n    color: var(--accent);\n    padding: 1px 5px;\n    border-radius: 3px;\n  }\n\n  /* ============ FLOW ARROW ============ */\n  .flow-arrow {\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    gap: 8px;\n    color: var(--text-dim);\n    font-family: var(--font-mono);\n    font-size: 12px;\n    padding: 4px 0;\n  }\n\n  .flow-arrow svg {\n    width: 20px;\n    height: 20px;\n    fill: none;\n    stroke: var(--border-bright);\n    stroke-width: 2;\n    stroke-linecap: round;\n    stroke-linejoin: round;\n  }\n\n  /* ============ PIPELINE ============ */\n  .pipeline {\n    display: flex;\n    gap: 0;\n    align-items: 