    padding: 0 4px;
    flex-shrink: 0;
  }

  /* ============ GOVERNANCE BAR ============ */
  .gov-bar {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
  }

  .gov-item {
    font-family: var(--font-mono);
    font-size: 9px;
    padding: 4px 8px;
    border-radius: 4px;
    background: var(--accent-dim);
    color: var(--accent);
    border: 1px solid var(--accent-dim);
  }

  .gov-item--automated {
    background: var(--green-dim);
    color: var(--green);
    border-color: var(--green-dim);
  }

  .gov-item--policy {
    background: var(--orange-dim);
    color: var(--orange);
    border-color: var(--orange-dim);
  }

  /* ============ TRANSFORMATION SECTION ============ */
  .trans-grid {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 16px;
  }

  .trans-col {
    display: flex;
    flex-direction: column;
    gap: 6px;
  }

  .trans-header {
    font-family: var(--font-mono);
    font-size: 11px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1px;
    padding: 8px 12px;
    border-radius: 6px;
    text-align: center;
  }

  .trans-header--bronze { background: var(--bronze-dim); color: var(--bronze); }
  .trans-header--silver { background: var(--silver-dim); color: var(--silver); }
  .trans-header--gold { background: var(--gold-dim); color: var(--gold); }

  .trans-item {
    background: var(--surface2);
    border: 1px solid var(--border);
    border-radius: 4px;
    padding: 6px 10px;
    font-size: 10px;
    display: flex;
    justify-content: space-between;
    align-items: center;
  }

  .trans-item .count {
    font-family: var(--font-mono);
    font-weight: 600;
    padding: 2px 6px;
    border-radius: 3px;
    font-size: 9px;
  }

  .trans-item .count--low { background: var(--green-dim); color: var(--green); }
  .trans-item .count--medium { background: var(--orange-dim); color: var(--orange); }
  .trans-item .count--high { background: var(--plum-dim); color: var(--plum); }

  /* ============ VOLUME BARS ============ */
  .volume-bar-container {
    display: flex;
    align-items: center;
    gap: 6px;
    font-family: var(--font-mono);
    font-size: 10px;
  }

  .volume-bar {
    height: 6px;
    border-radius: 3px;
    background: var(--border);
    flex: 1;
    overflow: hidden;
  }

  .volume-bar-fill {
    height: 100%;
    border-radius: 3px;
  }

  .volume-bar-fill--bronze { background: var(--bronze); }
  .volume-bar-fill--silver { background: var(--silver); }
  .volume-bar-fill--gold { background: var(--gold); }

  .volume-value {
    min-width: 45px;
    text-align: right;
    color: var(--text-dim);
  }

  /* ============ LEGEND ============ */
  .legend {
    display: flex;
    gap: 16px;
    flex-wrap: wrap;
  }

  .legend-item {
    display: flex;
    align-items: center;
    gap: 5px;
    font-size: 10px;
    color: var(--text-dim);
    font-family: var(--font-mono);
  }

  .legend-swatch {
    width: 10px;
    height: 10px;
    border-radius: 2px;
  }

  /* ============ CONSUMPTION GRID ============ */
  .consumption-grid {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 12px;
  }

  .consumption-card {
    background: var(--surface2);
    border: 1px solid var(--border);
    border-radius: 6px;
    padding: 10px 12px;
    font-size: 11px;
  }

  .consumption-card .card-title {
    font-weight: 600;
    margin-bottom: 2px;
  }

  .consumption-card .card-meta {
    color: var(--text-dim);
    font-family: var(--font-mono);
    font-size: 9px;
  }

  /* ============ SOURCE CATEGORY ============ */
  .source-grid {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 10px;
  }

  .source-category {
    background: var(--surface2);
    border: 1px solid var(--border);
    border-radius: 6px;
    padding: 10px 12px;
  }

  .source-category .cat-label {
    font-family: var(--font-mono);
    font-size: 9px;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: var(--text-dim);
    margin-bottom: 6px;
