  .source-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 10px;
    padding: 3px 0;
    border-bottom: 1px solid var(--border);
  }

  .source-item:last-child { border-bottom: none; }

  .source-item .vol {
    font-family: var(--font-mono);
    font-size: 9px;
    color: var(--text-dim);
  }

  /* ============ RESPONSIVE ============ */
  @media (max-width: 900px) {
    body { padding: 16px; }
    .pipeline-flow { grid-template-columns: 80px 1fr 60px 1fr 60px 1fr 60px 1fr 80px; }
    .trans-grid { grid-template-columns: 1fr; }
    .consumption-grid { grid-template-columns: 1fr 1fr; }
    .source-grid { grid-template-columns: 1fr 1fr; }
  }
</style>
</head>
<body>

<div class="diagram">
  <div class="section" style="--i:0">
    <h1>Data Lakehouse Architecture</h1>
    <p class="subtitle">Medallion Pipeline: Bronze / Silver / Gold — 10 Sources → 6 Consumption Endpoints</p>
  </div>

  <!-- SOURCE CATEGORIES -->
  <div class="section" style="--i:1">
    <div class="section-label"><span class="dot" style="background:var(--text-dim)"></span> Data Sources (5 Categories, 10 Sources)</div>
    <div class="source-grid">
      <div class="source-category">
        <div class="cat-label">IoT / Streaming</div>
        <div class="source-item"><span>IoT Sensors</span><span class="vol">450 GB</span></div>
        <div class="source-item"><span>Application Logs</span><span class="vol">320 GB</span></div>
        <div class="source-item"><span>Web Clickstream</span><span class="vol">210 GB</span></div>
      </div>
      <div class="source-category">
        <div class="cat-label">Enterprise Apps</div>
        <div class="source-item"><span>ERP System</span><span class="vol">120 GB</span></div>
        <div class="source-item"><span>CRM Platform</span><span class="vol">85 GB</span></div>
        <div class="source-item"><span>File Shares</span><span class="vol">45 GB</span></div>
      </div>
      <div class="source-category">
        <div class="cat-label">Databases</div>
        <div class="source-item"><span>Legacy RDBMS</span><span class="vol">95 GB</span></div>
        <div class="source-item"><span>NoSQL Stores</span><span class="vol">140 GB</span></div>
      </div>
      <div class="source-category">
        <div class="cat-label">External / 3rd Party</div>
        <div class="source-item"><span>Social Media APIs</span><span class="vol">60 GB</span></div>
        <div class="source-item"><span>Market Data Feeds</span><span class="vol">35 GB</span></div>
      </div>
      <div class="source-category">
        <div class="cat-label">Total Ingestion</div>
        <div class="source-item"><span>Stream (Kafka)</span><span class="vol">980 GB</span></div>
        <div class="source-item"><span>Batch (Spark/ADF)</span><span class="vol">520 GB</span></div>
        <div class="source-item"><span>CDC (Debezium)</span><span class="vol">60 GB</span></div>
      </div>
    </div>
  </div>

  <!-- MEDALLION LAYERS PIPELINE -->
  <div class="section" style="--i:2">
    <div class="section-label"><span class="dot" style="background:var(--accent)"></span> Medallion Pipeline — Data Flow &amp; Volumes</div>

    <div style="display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 16px; margin-bottom: 16px;">
      <!-- Bronze -->
      <div>
        <div class="trans-header trans-header--bronze">Bronze (Raw Zone)</div>
        <div class="trans-col">
          <div class="node-card node-card--bronze">
            <div class="node-label">Raw IoT Events</div>
            <div class="node-meta">450 GB/day · Delta/Parquet</div>
            <div class="volume-bar-container">
              <div class="volume-bar"><div class="volume-bar-fill volume-bar-fill--bronze" style="width:100%"></div></div>
              <span class="volume-value">450 GB</span>
            </div>
          </div>
          <div class="node-card node-card--bronze">
            <div class="node-label">Raw Log Data</div>
            <div class="node-meta">530 GB/day · Delta/Parquet</div>
            <div class="volume-bar-container">
              <div class="volume-bar"><div class="volume-bar-fill volume-bar-fill--bronze" style="width:100%"></div></div>
              <span class="volume-value">530 GB</span>
            </div>
          </div>
          <div class="node-card node-card--bronze">
            <div class="node-label">Raw Transactions</div>
            <div class="node-meta">300 GB/day · Delta/Parquet</div>
            <div class="volume-bar-container">
              <div class="volume-bar"><div class="volume-bar-fill volume-bar-fill--bronze" style="width:67%"></div></div>
              <span class="volume-value">300 GB</span>
            </div>
          </div>
          <div class="node-card node-card--bronze">
            <div class="node-label">Raw DB Snapshots</div>
            <div class="node-meta">185 GB/day · Delta/Parquet</div>
            <div class="volume-bar-container">
              <div class="volume-bar"><div class="volume-bar-fill volume-bar-fill--bronze" style="width:41%"></div></div>
              <span class="volume-value">185 GB</span>
            </div>
          </div>
          <div class="node-card node-card--bronze">
            <div class="node-label">Raw External Data</div>
            <div class="node-meta">95 GB/day · Delta/Parquet</div>
            <div class="volume-bar-container">
              <div class="volume-bar"><div class="volume-bar-fill volume-bar-fill--bronze" style="width:21%"></div></div>
              <span class="volume-value">95 GB</span>
            </div>
          </div>
        </div>
      </div>

      <!-- Silver -->
      <div>
        <div class="trans-header trans-header--silver">Silver (Curated Zone)</div>
        <div class="trans-col">
          <div class="node-card node-card--silver">
            <div class="node-label">Cleaned IoT Metrics</div>
            <div class="node-meta">180 GB/day · Delta</div>
            <div class="volume-bar-container">
              <div class="volume-bar"><div class="volume-bar-fill volume-bar-fill--silver" style="width:90%"></div></div>
              <span class="volume-value">180 GB</span>
            </div>
          </div>
          <div class="node-card node-card--silver">
            <div class="node-label">Sessionized Clickstream</div>
            <div class="node-meta">90 GB/day · Delta</div>
            <div class="volume-bar-container">
              <div class="volume-bar"><div class="volume-bar-fill volume-bar-fill--silver" style="width:45%"></div></div>
              <span class="volume-value">90 GB</span>
            </div>
          </div>
          <div class="node-card node-card--silver">
            <div class="node-label">Enriched Transactions</div>
            <div class="node-meta">110 GB/day · Delta</div>
            <div class="volume-bar-container">
              <div class="volume-bar"><div class="volume-bar-fill volume-bar-fill--silver" style="width:55%"></div></div>
              <span class="volume-value">110 GB</span>
            </div>
          </div>
          <div class="node-card node-card--silver">
            <div class="node-label">Unified Customer 360</div>
            <div class="node-meta">45 GB/day · Delta</div>
            <div class="volume-bar-container">
              <div class="volume-bar"><div class="volume-bar-fill volume-bar-fill--silver" style="width:23%"></div></div>
              <span class="volume-value">45 GB</span>
            </div>
          </div>
          <div class="node-card node-card--silver">
            <div class="node-label">Normalized Market Data</div>
            <div class="node-meta">20 GB/day · Delta</div>
            <div class="volume-bar-container">
              <div class="volume-bar"><div class="volume-bar-fill volume-bar-fill--silver" style="width:10%"></div></div>
              <span class="volume-value">20 GB</span>
            </div>
          </div>
        </div>
      </div>

      <!-- Gold -->
      <div>
        <div class="trans-header trans-header--gold">Gold (Business Zone)</div>
        <div class="trans-col">
          <div class="node-card node-card--gold">
            <div class="node-label">Revenue Aggregates</div>
            <div class="node-meta">8 GB/day · Delta</div>
            <div class="volume-bar-container">
              <div class="volume-bar"><div class="volume-bar-fill volume-bar-fill--gold" style="width:67%"></div></div>
              <span class="volume-value">8 GB</span>
            </div>
          </div>
          <div class="node-card node-card--gold">
            <div class="node-label">Anomaly Detection Features</div>
            <div class="node-meta">12 GB/day · Delta</div>
            <div class="volume-bar-container">
              <div class="volume-bar"><div class="volume-bar-fill volume-bar-fill--gold" style="width:100%"></div></div>
              <span class="volume-value">12 GB</span>
            </div>
          </div>
          <div class="node-card node-card--gold">
            <div class="node-label">Product Performance KPIs</div>
            <div class="node-meta">5 GB/day · Delta</div>
            <div class="volume-bar-container">
              <div class="volume-bar"><div class="volume-bar-fill volume-bar-fill--gold" style="width:42%"></div></div>
              <span class="volume-value">5 GB</span>
            </div>
          </div>
          <div class="node-card node-card--gold">
            <div class="node-label">Customer LTV Scores</div>
            <div class="node-meta">3 GB/day · Delta</div>
            <div class="volume-bar-container">
              <div class="volume-bar"><div class="volume-bar-fill volume-bar-fill--gold" style="width:25%"></div></div>
              <span class="volume-value">3 GB</span>
            </div>
          </div>
          <div class="node-card node-card--gold">
            <div class="node-label">Marketing Attribution</div>
            <div class="node-meta">4 GB/day · Delta</div>
            <div class="volume-bar-container">
              <div class="volume-bar"><div class="volume-bar-fill volume-bar-fill--gold" style="width:33%"></div></div>
              <span class="volume-value">4 GB</span>
            </div>
          </div>
        </div>
      </div>
    </div>

    <div class="legend">
      <div class="legend-item"><div class="legend-swatch" style="background:var(--bronze)"></div>Bronze (Raw)</div>
