      </div>
      <!-- Silver Transformations -->
      <div class="trans-col">
        <div class="trans-header trans-header--silver">Silver Transformations (34 total)</div>
        <div class="trans-item"><span>Null/Outlier Cleansing</span><span class="count count--medium">12</span></div>
        <div class="trans-item"><span>Join / Enrichment</span><span class="count count--high">8</span></div>
        <div class="trans-item"><span>PII Masking / Tokenization</span><span class="count count--medium">6</span></div>
        <div class="trans-item"><span>Schema Conformance (SCD2)</span><span class="count count--high">5</span></div>
        <div class="trans-item"><span>Sessionization</span><span class="count count--high">3</span></div>
      </div>
      <!-- Gold Transformations -->
      <div class="trans-col">
        <div class="trans-header trans-header--gold">Gold Transformations (30 total)</div>
        <div class="trans-item"><span>Aggregation / Roll-up</span><span class="count count--medium">10</span></div>
        <div class="trans-item"><span>Business Logic / KPI Calc</span><span class="count count--high">8</span></div>
        <div class="trans-item"><span>Feature Engineering</span><span class="count count--high">7</span></div>
        <div class="trans-item"><span>Materialized Views</span><span class="count count--medium">5</span></div>
      </div>
    </div>
  </div>

  <!-- GOVERNANCE OVERLAY -->
  <div class="section" style="--i:4">
    <div class="section-label"><span class="dot" style="background:var(--plum)"></span> Governance Controls (15 policies across all layers)</div>
    <div style="display: grid; grid-template-columns: repeat(5, 1fr); gap: 12px;">
