      </div>
      <div>
        <div style="font-family: var(--font-mono); font-size: 9px; text-transform: uppercase; letter-spacing: 1px; color: var(--silver); margin-bottom: 6px;">Silver</div>
        <div class="gov-item gov-item--policy">Column-Level Encryption</div>
        <div class="gov-item gov-item--automated">Data Lineage Capture</div>
        <div class="gov-item gov-item--policy">Row-Level Security</div>
      </div>
      <div>
        <div style="font-family: var(--font-mono); font-size: 9px; text-transform: uppercase; letter-spacing: 1px; color: var(--gold); margin-bottom: 6px;">Gold</div>
        <div class="gov-item gov-item--policy">RBAC Access Control</div>
        <div class="gov-item">Data Certification</div>
