  <!-- CONSUMPTION FANOUT -->
  <div class="section" style="--i:5">
    <div class="section-label"><span class="dot" style="background:var(--plum)"></span> Consumption Fanout (6 Endpoints)</div>
    <div class="consumption-grid">
      <div class="consumption-card" style="border-left: 3px solid var(--plum);">
        <div class="card-title">Executive Dashboards</div>
        <div class="card-meta">Power BI / Tableau · Revenue Aggregates, Product KPIs, Customer LTV</div>
      </div>
      <div class="consumption-card" style="border-left: 3px solid var(--plum);">
        <div class="card-title">Ad-hoc SQL Analytics</div>
        <div class="card-meta">Serverless SQL · Revenue Aggregates, Marketing Attribution</div>
