    </div>
  </div>

  <!-- KEY METRICS -->
  <div class="section" style="--i:6; display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px;">
    <div style="text-align: center;">
      <div style="font-size: 28px; font-weight: 700; font-variant-numeric: tabular-nums;">1,560</div>
